Bytes ScriptSession::encodeMirrorImages(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=16u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty())throw std::runtime_error("Mirror image snapshot requires a quiescent local session");std::vector<std::pair<std::uint32_t,std::uint32_t>> entries;std::set<std::uint32_t> stable;for(auto& [id,unit]:units_)if(unit->mirrorImage){auto& state=*unit->mirrorImage;auto mapped=encodeHandle?encodeHandle("unit",id):0;if(!alive(id,NativeKind::Unit) || !mapped || !stable.insert(mapped).second || state.owner>=16 || !unit->cast || unit->cast->ticket!=state.ticket || state.spell.kind!=SpellKind::MirrorImage || !std::isfinite(state.remaining) || state.remaining<0)throw std::runtime_error("Invalid mirror image state");entries.emplace_back(mapped,id);}if(entries.size()>65536)throw std::runtime_error("Mirror image snapshot exceeds budget");std::sort(entries.begin(),entries.end());SnapshotWriter out(budget-64);out.u32(tag("SMIR"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.size(entries.size());for(auto [mapped,id]:entries){auto& state=*units_.at(id)->mirrorImage;out.u32(mapped);writeSpellSnapshot(out,state.spell);out.u32(state.owner);out.u64(state.ticket);out.u64(std::bit_cast<std::uint64_t>(state.remaining));}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreMirrorImages(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=16u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || mirrorImagesRestored_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Mirror image restore requires rebuilt casts before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("SMIR"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Mirror image snapshot map or clock differs");auto count=in.count(24,65536);std::map<std::uint32_t,MirrorImageState> pending;std::set<std::uint32_t> stableIds;for(unsigned i=0;i<count;++i){auto stable=in.u32(),id=decodeHandle?decodeHandle("unit",stable):0;auto spell=readSpellSnapshot(in);auto owner=in.u32();auto ticket=snapshotU64(in);auto remaining=std::bit_cast<double>(snapshotU64(in));if(!stable || !stableIds.insert(stable).second || !unitIdentityHandles_.contains(stable) || unitIdentityHandles_.at(stable)!=id || !alive(id,NativeKind::Unit) || !units_.contains(id) || owner>=16 || !units_.at(id)->cast || units_.at(id)->cast->ticket!=ticket || spell.kind!=SpellKind::MirrorImage || !std::isfinite(remaining) || remaining<0 || !pending.emplace(id,MirrorImageState{std::move(spell),owner,ticket,remaining}).second)throw std::runtime_error("Invalid mirror image state");}in.finish();for(auto& [id,unit]:units_)if(unit->mirrorImage)throw std::runtime_error("Mirror image target already has state");for(auto& [id,state]:pending)units_.at(id)->mirrorImage=std::move(state);if(!pending.empty())++fogRevision_;mirrorImagesRestored_=true;
}
std::pair<float,bool> ScriptSession::windWalkStrike(const UnitState& u){
    std::pair<float,bool> result{};for(auto& [id,b]:u.buffs)if(b.kind==BuffKind::WindWalk && !b.stealthDisabled && b.fadeRemaining<=0 && b.remaining>0 && b.stealthDamage>result.first)result={b.stealthDamage,b.backstab};return result;
}
std::optional<WorldPoint> ScriptSession::blinkPoint(const UnitState& u,const SpellInfo& s,WorldPoint point){
    float x=number(u.x),y=number(u.y),dx=number(point.x)-x,dy=number(point.y)-y,distance=std::hypot(dx,dy);if(!std::isfinite(distance) || distance<.001f)return {};dx/=distance;dy/=distance;distance=std::clamp(distance,s.secondary,s.amount);float desiredX=x+dx*distance,desiredY=y+dy*distance;bool flying=u.movementType=="fly";
    for(unsigned ring=0;ring<=8;++ring)for(unsigned side=0;side<(ring?16u:1u);++side){float angle=float(side)*6.28318530718f/16;auto candidate=requireWorld().clamp({real(desiredX+std::cos(angle)*ring*32),real(desiredY+std::sin(angle)*ring*32)});float cx=number(candidate.x),cy=number(candidate.y),range=std::hypot(cx-x,cy-y);if(range>s.amount+.01f || range+.01f<s.secondary)continue;if(u.pathing){auto route=requireWorld().route(candidate,candidate,u.collision,pathMovement(u.movementType));if(route.empty() || std::hypot(number(route.back().x)-cx,number(route.back().y)-cy)>1)continue;}bool free=true;for(auto& [id,other]:units_)if(id!=u.handle && !other->hidden() && other->pathing && number(other->life)>0 && (other->movementType=="fly")==flying && std::hypot(number(other->x)-cx,number(other->y)-cy)<u.collision+other->collision){free=false;break;}if(free)return candidate;}return {};
}
void ScriptSession::blinkSpell(std::uint32_t id,const SpellInfo& s,WorldPoint point){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);auto destination=blinkPoint(*u,s,point);if(!destination)return;spellVisual(s,"Specialart",0,{u->x,u->y});u->x=destination->x;u->y=destination->y;u->route.clear();u->waypoint=0;u->combat.home=*destination;unitFootprint(*u);++fogRevision_;spellVisual(s,"Areaeffectart",0,*destination);
}
void ScriptSession::startMirrorImage(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);u->mirrorImage=MirrorImageState{cast.spell,u->owner,cast.ticket,cast.spell.impactDelay};u->route.clear();u->waypoint=0;for(auto it=u->buffs.begin();it!=u->buffs.end();)if(!it->second.positive){releaseBuff(it->second);it=u->buffs.erase(it);}else ++it;spellVisual(cast.spell,"Specialart",0,{u->x,u->y});++fogRevision_;
    std::vector<std::uint32_t> previous;for(auto& [cloneId,clone]:units_)if(clone->illusion && clone->summoner==id && clone->summonAbility==cast.spell.ability)previous.push_back(cloneId);for(auto cloneId:previous){if(!alive(id,NativeKind::Unit) || u->removing || u->owner!=cast.owner || !u->mirrorImage || !u->cast || u->cast->ticket!=cast.ticket)return;removeUnit(cloneId);}
}
